15	// Caps on the Message section of a finding detail (DEVDESK-750): a scanner can
16	// hand back a whole stderr, and the detail shows the start of it.
17	const (
18		maxMessageWidth = 110
19		maxMessageLines = 8
20	)
21	
22	// scanMount is where a scanned directory is mounted inside a scanner container
23	// (scan.containerScanPath, unexported there).
24	const scanMount = "/scan"
25	
26	// pathToken finds an absolute path in a text: it starts at the beginning of the
27	// text or after a character that cannot be part of a path name, and stops at
28	// white space or punctuation that ends a path in a message.
29	var pathToken = REDACTED
30	
31	// shortPaths rewrites absolute paths inside text for display: "<target>/" and
32	// the container mount "/scan/" are removed, a bare target becomes ".", and any
33	// other path under HOME is folded to "~/". target is used only when it is an
34	// absolute path (an image reference is ignored). Display only: the finding
35	// keeps its text.
36	func shortPaths(text, target string) string {
37		if text == "" {
38			return ""
39		}
40		root := ""
41		if filepath.IsAbs(target) {
42			if root = filepath.ToSlash(filepath.Clean(target)); root == "/" {
43				root = ""
44			}
45		}
46		return pathToken.ReplaceAllStringFunc(text, func(match string) string {
47			at := strings.IndexByte(match, '/')
48			path, tail := match[at:], ""
49			// A sentence can end on a path: "cannot read /repo."
50			if trimmed := strings.TrimRight(path, "."); trimmed != "" {
51				path, tail = trimmed, path[len(trimmed):]
52			}
53			return match[:at] + shortPath(path, root) + tail
54		})
55	}
56	
57	// shortPath shortens one absolute path: relative to the target, relative to the
58	// container mount, or folded under HOME.
59	func shortPath(path, root string) string {
60		for _, base := range []string{root, scanMount} {
61			switch {
62			case base == "":
63			case path == base:
64				return "."
65			case strings.HasPrefix(path, base+"/"):
66				if rest := strings.TrimLeft(path[len(base):], "/"); rest != "" {
67					return rest
68				}
69				return "."
70			}
71		}
72		return theme.FoldHome(path)
73	}
74	
75	// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
76	// It measures with x/ansi, as the viewport does, not with runewidth.
77	func oneLine(text string, width int) string {
78		if width <= 0 {
79			return ""
80		}
81		first, _, _ := strings.Cut(text, "\n")
82		first = strings.TrimSuffix(first, "\r")
83		if ansi.StringWidth(first) <= width {
84			return first
85		}
86		return ansi.Truncate(first, width, theme.Ellipsis)
87	}
88	
89	// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
90	// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
91	// lines left out. A blank text gives nil, 0.
92	func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
93		if strings.TrimSpace(text) == "" {
94			return nil, 0
95		}
96		text = strings.TrimRight(text, " \t\r\n")
97		lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
98		if len(lines) > maxLines {
99			return lines[:maxLines], len(lines) - maxLines
100		}
101		return lines, 0
102	}
103	
104	// moreLines is the marker after a capped text, "" when nothing was left out.
105	func moreLines(n int) string {
106		switch {
107		case n <= 0:
108			return ""
109		case n == 1:
110			return "… 1 more line"
111		}
112		return fmt.Sprintf("… %d more lines", n)
113	}
114	
115	// scrollPosition is "Lines a-b of N" when the content is taller than the
116	// viewport, "" otherwise.
117	func scrollPosition(offset, visible, total int) string {
118		if visible <= 0 || total <= visible {
119			return ""
120		}
121		offset = max(offset, 0)
122		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
123	}
124	
125	// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
126	// return has no width the viewport and the terminal agree on, trailing spaces
127	// are noise, and a run of blank lines is one blank line. dropBlank removes the
128	// blank lines altogether (a stderr, where they separate nothing).
129	func normalizeText(text string, dropBlank bool) string {
130		text = strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\t", "    ")
131		var out []string
132		for _, line := range strings.Split(text, "\n") {
133			line = strings.TrimRight(line, " ")
134			blank := line == ""
135			switch {
136			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
137			default:
138				out = append(out, line)
139			}
140		}
141		for len(out) > 0 && out[len(out)-1] == "" {
142			out = out[:len(out)-1]
143		}
144		return strings.Join(out, "\n")
145	}
146	
147	// dropBlankLines is normalizeText without any blank line.
148	func dropBlankLines(text string) string { return normalizeText(text, true) }
149	
150	// detailsText lays text out for the finding detail: every line it returns is
151	// styled on the theme background and spans at most width cells, measured with
152	// x/ansi as the viewport does.
153	type detailsText struct {
154		width int            // cells a line may span
155		text  lipgloss.Style // ordinary text
156		dim   lipgloss.Style // secondary text
157	}
158	
159	func newDetailsText(width int) detailsText {
160		return detailsText{
161			width: width,
162			text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
163			dim:   theme.DimStyle,
164		}
165	}
166	
167	// block wraps text at the full width, one styled line per entry.
168	func (t detailsText) block(text string, style lipgloss.Style) []string {
169		return t.indented("", text, style)
170	}
171	
172	// indented wraps text under a prefix of spaces.
173	func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
174		text = normalizeText(text, false)
175		if text == "" {
176			return nil
177		}
178		room := max(t.width-ansi.StringWidth(prefix), 1)
179		var lines []string
180		for _, line := range strings.Split(ansi.Wrap(text, room, ""), "\n") {
181			line = strings.TrimRight(line, " ")
182			if line == "" {
183				lines = append(lines, "")
184				continue
185			}
186			lines = append(lines, theme.Bg(prefix)+style.Render(line))
187		}
188		return lines
189	}
190	
191	// field is a label and its value, the value wrapped under itself. When the label
192	// leaves too little room for the value, the value goes on the lines below.
193	func (t detailsText) field(label, value string, style lipgloss.Style) []string {
194		value = normalizeText(value, false)
195		if value == "" {
196			return nil
197		}
198		labelWidth := ansi.StringWidth(label)
199		if t.width-labelWidth < minFieldValueWidth {
200			return append([]string{theme.SubTitleStyle.Render(strings.TrimRight(label, " "))}, t.block(value, style)...)
201		}
202		lines := strings.Split(ansi.Wrap(value, t.width-labelWidth, ""), "\n")
203		out := make([]string, 0, len(lines))
204		for i, line := range lines {
205			line = style.Render(strings.TrimRight(line, " "))
206			if i == 0 {
207				out = append(out, theme.SubTitleStyle.Render(label)+line)
208			} else {
209				out = append(out, theme.Bg(strings.Repeat(" ", labelWidth))+line)
210			}
211		}
212		return out
213	}
214	
215	// minFieldValueWidth is the least room a value needs beside its label.
216	const minFieldValueWidth = 12
